1	{% extends "base.html" %}
2	{% block title %}{% if observation %}Edit observation{% else %}New observation{% endif %}{% endblock %}
3	{% block content %}
4	<h1>{% if observation %}Edit observation{% else %}New observation{% endif %}</h1>
5	{% comment %}
6	The mood field is deliberately a select rather than radio buttons because
7	the safeguarding lead asked for it to match the paper form; do not change
8	it without asking her first.
9	{% endcomment %}
10	<form method="post">
11	  {% csrf_token %}
12	  {{ form.non_field_errors }}
13	  <p>{{ form.pupil.label_tag }} {{ form.pupil }} {{ form.pupil.errors }}</p>
14	  <p>{{ form.observed_on.label_tag }} {{ form.observed_on }} {{ form.observed_on.errors }}</p>
15	  <p>{{ form.mood.label_tag }} {{ form.mood }} {{ form.mood.errors }}</p>
16	  <p>{{ form.body.label_tag }} {{ form.body }} {{ form.body.errors }}</p>
17	  <p>{{ form.agreed_action.label_tag }} {{ form.agreed_action }} {{ form.agreed_action.errors }}</p>
18	  <button type="submit">Save</button>
19	</form>
20	{% endblock %}
